/**
 * WordRam - Data & Pedagogical Architecture (v42)
 * Multilingual Word Engine: English (CEFR) & Chechen (1500 normative words)
 * Universal Grapheme Tokenization, Dynamic Difficulty, Offline PWA.
 */

class WordRamTokenizer {
  static MULTI_GRAPHEMES_CHECHEN = ["АЬ", "ОЬ", "УЬ", "ГӀ", "КХ", "КЪ", "КӀ", "ПӀ", "ТӀ", "ХЬ", "ХӀ", "ЦӀ", "ЧӀ"];
  static CYRILLIC_LETTERS_CHECHEN = new Set("АБВГДЕЁЖЗИЙКЛМНОПРСТУФХЦЧШЩЪЫЬЭЮЯӀ");

  static normalizeChechen(word) {
    if (!word) return "";
    let w = String(word).trim().toUpperCase();
    w = w.replace(/[\u04CF\u04C0Il1|]/g, "\u04C0");
    w = w.replace(/ъ/g, "Ъ").replace(/ь/g, "Ь");
    return w;
  }

  static tokenizeChechen(word) {
    const w = WordRamTokenizer.normalizeChechen(word);
    const tiles = [];
    let i = 0;
    while (i < w.length) {
      if (i + 2 <= w.length && WordRamTokenizer.MULTI_GRAPHEMES_CHECHEN.includes(w.slice(i, i + 2))) {
        tiles.push(w.slice(i, i + 2));
        i += 2;
      } else if (WordRamTokenizer.CYRILLIC_LETTERS_CHECHEN.has(w[i])) {
        tiles.push(w[i]);
        i += 1;
      } else {
        if (w[i] !== " " && w[i] !== "-") {
          tiles.push(w[i]);
        }
        i += 1;
      }
    }
    return tiles;
  }

  static reconstructChechen(tiles) {
    if (!tiles || !Array.isArray(tiles)) return "";
    return tiles.join("");
  }

  static tokenizeEnglish(word) {
    if (!word) return [];
    const w = String(word).trim().toUpperCase();
    return w.split("");
  }

  static reconstructEnglish(tiles) {
    if (!tiles || !Array.isArray(tiles)) return "";
    return tiles.join("");
  }

  static tokenize(word, lang = "english") {
    if (lang === "chechen") {
      return WordRamTokenizer.tokenizeChechen(word);
    }
    return WordRamTokenizer.tokenizeEnglish(word);
  }

  static reconstruct(tiles, lang = "english") {
    if (lang === "chechen") {
      return WordRamTokenizer.reconstructChechen(tiles);
    }
    return WordRamTokenizer.reconstructEnglish(tiles);
  }

  static getTileCount(word, lang = "english") {
    return WordRamTokenizer.tokenize(word, lang).length;
  }
}

